<?php
declare(strict_types=1);
require __DIR__ . '/config.php';
if (!isAdmin()) { header('Location: auth.php'); exit; }
$error = '';
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    try {
        $action = $_POST['action'] ?? '';
        if ($action === 'category-create') db()->prepare('INSERT INTO categories(title,slug,sort_order) VALUES(?,?,?)')->execute([trim($_POST['title']), trim($_POST['slug']), (int)$_POST['sort_order']]);
        if ($action === 'category-update') db()->prepare('UPDATE categories SET title=?,slug=?,sort_order=? WHERE id=?')->execute([trim($_POST['title']),trim($_POST['slug']),(int)$_POST['sort_order'],(int)$_POST['id']]);
        if ($action === 'category-delete') db()->prepare('DELETE FROM categories WHERE id=?')->execute([(int)$_POST['id']]);
        if ($action === 'playlist-save') { $data = [(int)$_POST['category_id'],trim($_POST['title']),trim($_POST['description']), (int)$_POST['channels'],trim($_POST['quality']),trim($_POST['cover_color']),trim($_POST['playlist_url']),isset($_POST['is_active']) ? 1 : 0]; if (!empty($_POST['id'])) { $data[]=(int)$_POST['id']; db()->prepare('UPDATE playlists SET category_id=?,title=?,description=?,channels=?,quality=?,cover_color=?,playlist_url=?,is_active=? WHERE id=?')->execute($data); } else db()->prepare('INSERT INTO playlists(category_id,title,description,channels,quality,cover_color,playlist_url,is_active) VALUES(?,?,?,?,?,?,?,?)')->execute($data); }
        if ($action === 'playlist-delete') db()->prepare('DELETE FROM playlists WHERE id=?')->execute([(int)$_POST['id']]);
        header('Location: admin.php?tab=' . urlencode($_POST['tab'] ?? 'playlists')); exit;
    } catch (PDOException $e) { $error = 'Не удалось сохранить изменения. Проверьте уникальность названия/slug и наличие плейлистов в категории.'; }
}
$categories = db()->query('SELECT * FROM categories ORDER BY sort_order,title')->fetchAll(); $playlists = db()->query('SELECT p.*,c.title category_title FROM playlists p JOIN categories c ON c.id=p.category_id ORDER BY p.id DESC')->fetchAll(); $editId=(int)($_GET['edit']??0); $edit=array_values(array_filter($playlists,fn($p)=>$p['id']===$editId))[0]??null; $tab=$_GET['tab']??'playlists';
?><!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Панель управления — BOMBALA</title><link rel="stylesheet" href="styles.css"></head><body><header class="topbar"><a class="logo" href="index.php"><img src="assets/bombala-logo.png" alt="BOMBALA"></a><nav><a href="index.php">На сайт</a></nav><a class="login" href="index.php?logout=1">Выйти</a></header><main class="admin"><p class="eyebrow">● &nbsp; Администрирование</p><h1>Панель управления</h1><div class="tabs admin-tabs"><a class="<?= $tab==='playlists'?'active':'' ?>" href="?tab=playlists">Плейлисты</a><a class="<?= $tab==='categories'?'active':'' ?>" href="?tab=categories">Категории</a></div><?php if($error): ?><p class="error"><?= e($error) ?></p><?php endif; ?><?php if($tab==='categories'): ?><section class="manager"><div><h2>Категории</h2><?php foreach($categories as $c): ?><form class="row-form" method="post"><input type="hidden" name="action" value="category-update"><input type="hidden" name="id" value="<?= $c['id'] ?>"><input name="title" value="<?= e($c['title']) ?>"><input name="slug" value="<?= e($c['slug']) ?>"><input name="sort_order" type="number" value="<?= $c['sort_order'] ?>"><button>Сохранить</button></form><form class="inline" method="post"><input type="hidden" name="action" value="category-delete"><input type="hidden" name="id" value="<?= $c['id'] ?>"><input type="hidden" name="tab" value="categories"><button class="danger">Удалить</button></form><?php endforeach; ?></div><form class="editor" method="post"><h2>Новая категория</h2><input type="hidden" name="action" value="category-create"><input type="hidden" name="tab" value="categories"><label>Название<input name="title" required></label><label>Slug (латиница)<input name="slug" pattern="[a-z0-9-]+" required></label><label>Порядок<input name="sort_order" type="number" value="0"></label><button>Создать категорию</button></form></section><?php else: ?><section class="manager"><div><h2>Все плейлисты</h2><?php foreach($playlists as $p): ?><div class="playlist-row"><span><b><?= e($p['title']) ?></b><small><?= e($p['category_title']) ?> · <?= $p['channels'] ?> каналов · <?= $p['is_active']?'Активен':'Скрыт' ?></small></span><a href="?edit=<?= $p['id'] ?>">Изменить</a><form method="post"><input type="hidden" name="action" value="playlist-delete"><input type="hidden" name="id" value="<?= $p['id'] ?>"><button class="danger">Удалить</button></form></div><?php endforeach; ?></div><form class="editor" method="post"><h2><?= $edit?'Редактирование':'Новый плейлист' ?></h2><input type="hidden" name="action" value="playlist-save"><input type="hidden" name="id" value="<?= $edit['id']??'' ?>"><label>Название<input name="title" value="<?= e($edit['title']??'') ?>" required></label><label>Категория<select name="category_id"><?php foreach($categories as $c): ?><option value="<?= $c['id'] ?>" <?= ($edit['category_id']??0)==$c['id']?'selected':'' ?>><?= e($c['title']) ?></option><?php endforeach; ?></select></label><label>Описание<textarea name="description"><?= e($edit['description']??'') ?></textarea></label><label>Каналов<input name="channels" type="number" min="1" value="<?= $edit['channels']??1 ?>"></label><label>Качество<input name="quality" value="<?= e($edit['quality']??'HD') ?>"></label><label>Цвет обложки<input name="cover_color" type="color" value="<?= e($edit['cover_color']??'#6d4aff') ?>"></label><label>M3U ссылка<input type="url" name="playlist_url" value="<?= e($edit['playlist_url']??'') ?>" required></label><label class="check"><input type="checkbox" name="is_active" <?= !isset($edit)||$edit['is_active']?'checked':'' ?>> Показывать на сайте</label><button><?= $edit?'Сохранить изменения':'Добавить плейлист' ?></button></form></section><?php endif; ?></main></body></html>
